def expected_maximum(m, n):
    # The expected value of the maximum of m independent random variables, each uniformly distributed on [1, 2, ..., m],
    # is given by the formula: m + (m/2) * (1/m)^(n-1) for n > 1 and m for n == 1.

    if n == 1:
        return float(m)
    else:
        return m + (m / 2) * (1 / m) ** (n - 1)

