import math

def expected_maximum(m, n):
    def f(x):
        return (m - x + 1) * math.pow(m, n - 1) / math.pow(m - 1, n - 1)

    def g(x):
        return (m - x) * math.pow(m, n - 1) / math.pow(m - 1, n - 1)

    left, right = 1, m
    while right - left > 1e-7:
        mid = (left + right) / 2
        if f(mid) > g(mid):
            left = mid
        else:
            right = mid

    return f(left)

